import React, { useEffect, useState, useRef } from 'react';
import { DataTable } from 'primereact/datatable';
import { Column } from 'primereact/column';
import { Tag } from 'primereact/tag';
import { Button } from 'primereact/button';
import { InputText } from 'primereact/inputtext';
import { InputNumber } from 'primereact/inputnumber';
import { db } from '../firebase';
import { collection, onSnapshot, deleteDoc, doc, updateDoc } from 'firebase/firestore';

export default function OrderList() {
  const [orders, setOrders] = useState([]);
  const [expandedRows, setExpandedRows] = useState([]);
  const [editingRows, setEditingRows] = useState({});
  const tableRef = useRef(null);

  useEffect(() => {
    const unsub = onSnapshot(collection(db, 'orders'), (snapshot) => {
      const items = snapshot.docs.map(doc => {
        const data = doc.data();
        let normalizedDate = '';
  
        try {
          const d = new Date(data.date);
          normalizedDate = d.toISOString().slice(0, 10); // YYYY-MM-DD
        } catch {
          normalizedDate = data.date || ''; // fallback
        }
  
        return { ...data, createdAt: normalizedDate, docId: doc.id };
      });
      setOrders(items);
    });
  
    return () => unsub();
  }, []);

  const total = orders.reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0);

  const formatDate = (dateStr) => {
    try {
      const d = new Date(dateStr);
      return d.toLocaleDateString('en-IN', {
        weekday: 'short',
        year: 'numeric',
        month: 'short',
        day: 'numeric',
      });
    } catch {
      return 'Invalid Date';
    }
  };

  const amountTemplate = (rowData) => {
    const amount = parseFloat(rowData.amount);
    return isNaN(amount) ? '₹0.00' : `₹${amount.toFixed(2)}`;
  };

  const exportCSV = () => {
    if (tableRef.current) {
      tableRef.current.exportCSV();
    }
  };

  const deleteOrder = async (rowData) => {
    if (window.confirm('Delete this order?')) {
      await deleteDoc(doc(db, 'orders', rowData.docId));
    }
  };

  const onRowEditComplete = async (e) => {
    const { newData, index } = e;
    if (!newData.docId) return;

    const docRef = doc(db, 'orders', newData.docId);
    await updateDoc(docRef, {
      description: newData.description,
      amount: parseFloat(newData.amount),
      tower: newData.tower,
      flat:newData.flat
    });
  };

  const createHeaderTemplate = (allData) => (groupRow) => {
    const groupDate = groupRow.date;
    const dayTotal = allData
      .filter(item => item.date === groupDate)
      .reduce((sum, item) => sum + (parseFloat(item.amount) || 0), 0);

    return (
      <React.Fragment>
        <span className="fw-bold">{formatDate(groupDate)}</span>
        <span style={{ marginLeft: 'auto', float: 'right' }} className="text-success fw-bold">
          Total: ₹{dayTotal.toFixed(2)}
        </span>
      </React.Fragment>
    );
  };

  return (
    <div className="card p-3 mb-3">
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h5 className="mb-0">Orders List</h5>
        <div className="d-flex gap-2 align-items-center">
          <Tag severity="success" value={`Total: ₹${total.toFixed(2)}`} />
          <Button icon="pi pi-file-export" className="p-button-sm" onClick={exportCSV} />
        </div>
      </div>

      <DataTable
        ref={tableRef}
        value={orders}
        editMode="row"
        dataKey="docId"
        rowEditorValidator={() => true}
        onRowEditComplete={onRowEditComplete}
        rowGroupMode="subheader"
        groupRowsBy="date"
        sortField="createdAt"
        sortOrder={-1}
        expandableRowGroups
        expandedRows={expandedRows}
        onRowToggle={(e) => {
          // e.data is the new array of expanded group‑rows
          const lastRow = e.data.length ? e.data[e.data.length - 1] : null;
          setExpandedRows(lastRow ? [lastRow] : []);          // keep exactly one
        }}
        rowGroupHeaderTemplate={createHeaderTemplate(orders)}
        scrollable
        responsiveLayout="scroll"
        
      >
        <Column field="createdAt" header="Date" className="invisible" />
        <Column field="description" header="Description" editor={(options) => (
          <InputText value={options.value} onChange={(e) => options.editorCallback(e.target.value)} />
        )} />
        <Column field="amount" header="Amount" body={amountTemplate} editor={(options) => (
          <InputNumber
            value={options.value}
            onValueChange={(e) => options.editorCallback(e.value)}
            mode="currency"
            currency="INR"
            locale="en-IN"
          />
        )} />
        <Column field="tower" header="Tower" editor={(options) => (
          <InputText value={options.value} onChange={(e) => options.editorCallback(e.target.value)} />
        )} />
        <Column field="flat" header="Flat"  editor={(options) => (
          <InputText value={options.value} onChange={(e) => options.editorCallback(e.target.value)} />
        )}/>
        <Column rowEditor />
        <Column
         
          body={(rowData) => (
            <Button icon="pi pi-trash" className="p-button-danger p-button-sm" onClick={() => deleteOrder(rowData)} />
          )}
          style={{ width: '4rem', textAlign: 'center' }}
        />
      </DataTable>
    </div>
  );
}
