import React, { useState } from 'react';
import { InputText } from 'primereact/inputtext';
import { Calendar } from 'primereact/calendar';
import { InputNumber } from 'primereact/inputnumber';
import { Button } from 'primereact/button';
import { db } from '../firebase'; // adjust path if needed
import { collection, addDoc } from 'firebase/firestore';

export default function OrderForm() {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState(null);
  const [date, setDate] = useState(null);
  const [loading, setLoading] = useState(false);
  const [tower, setTower] = useState('');
  const [flat, setFlat] = useState('');
  const submit = async (e) => {
    e.preventDefault();
    if (!description || !amount || !date) return;

    const formattedDate = date.toLocaleDateString('en-CA'); // 'YYYY-MM-DD'
    setLoading(true);
    try {
      await addDoc(collection(db, 'orders'), {
        description,
        amount,
        date: formattedDate,
        createdAt: new Date(),
        tower,
        flat
      });
      setDescription('');
      setAmount(null);
      setDate(null);
      setTower('');
      setFlat('');
    } catch (err) {
      console.error('Failed to add order:', err);
    }
    setLoading(false);
  };

  return (
    <form onSubmit={submit} className="p-3 border rounded mb-3 bg-white">
      <h5>Add Order</h5>
      <div className="mb-2">
        <InputText placeholder="Description" value={description} onChange={e => setDescription(e.target.value)} className="w-100" />
      </div>
      <div className="mb-2">
        <InputNumber value={amount} onValueChange={e => setAmount(e.value)} placeholder="Amount" mode="currency" currency="INR" locale="en-IN" className="w-100" />
      </div>
      <div className="mb-2">
        <InputText placeholder="Tower" value={tower} onChange={e => setTower(e.target.value)} className="w-100" />
      </div>
      <div className="mb-2">
        <InputText placeholder="Flat No." value={flat} onChange={e => setFlat(e.target.value)} className="w-100" />
      </div>
      <div className="mb-3">
        <Calendar value={date} onChange={e => setDate(e.value)} placeholder="Date" showIcon className="w-100" />
      </div>
      <Button label={loading ? "Adding..." : "Add Order"} icon="pi pi-check" type="submit" className="p-button-primary w-100" disabled={loading} />
    </form>
  );
}
