import React, { useState } from 'react';
import { InputText } from 'primereact/inputtext';
import { Calendar } from 'primereact/calendar';
import { InputNumber } from 'primereact/inputnumber';
import { Button } from 'primereact/button';
import { db } from '../firebase'; // adjust path if needed
import { collection, addDoc } from 'firebase/firestore';

export default function ExpenseForm() {
  const [desc, setDesc] = useState('');
  const [amount, setAmount] = useState(null);
  const [date, setDate] = useState(null);
  const [loading, setLoading] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    if (!desc || !amount || !date) return;

    const formattedDate = date.toLocaleDateString('en-CA');
    setLoading(true);
    try {
      await addDoc(collection(db, 'expenses'), {
        desc,
        amount,
        date: formattedDate,
        createdAt: new Date()
      });
      setDesc('');
      setAmount(null);
      setDate(null);
    } catch (err) {
      console.error('Failed to add expense:', err);
    }
    setLoading(false);
  };

  return (
    <form onSubmit={submit} className="p-3 border rounded mb-3 bg-white">
      <h5>Add Expense</h5>
      <div className="mb-2">
        <InputText placeholder="Description" value={desc} onChange={e => setDesc(e.target.value)} className="w-100" />
      </div>
      <div className="mb-2">
        <InputNumber value={amount} onValueChange={e => setAmount(e.value)} placeholder="Amount" mode="currency" currency="INR" locale="en-IN" className="w-100" />
      </div>
      <div className="mb-3">
        <Calendar value={date} onChange={e => setDate(e.value)} placeholder="Date" showIcon className="w-100" />
      </div>
      <Button label={loading ? "Adding..." : "Add Expense"} icon="pi pi-check" type="submit" className="p-button-danger w-100" disabled={loading} />
    </form>
  );
}
