import React from 'react';
import Highcharts from 'highcharts';
import HighchartsReact from 'highcharts-react-official';
import { Card } from 'primereact/card';
import { Chart } from 'primereact/chart';
export default function Summary({ orders, expenses }) {
  
  const groupByDate = (data) =>
    data.reduce((acc, item) => {
      if (!item?.date || isNaN(item?.amount)) return acc;
      acc[item.date] = (acc[item.date] || 0) + Number(item.amount);
      return acc;
    }, {});

  const orderTotals = groupByDate(orders || []);
  const expenseTotals = groupByDate(expenses || []);

  const allDates = Array.from(
    new Set([...Object.keys(orderTotals), ...Object.keys(expenseTotals)])
  ).sort();

  const orderChartData = allDates.map((date) => orderTotals[date] || 0);
  const expenseChartData = allDates.map((date) => expenseTotals[date] || 0);

  const totalOrderAmount = orders.reduce((sum, o) => sum + (parseFloat(o.amount) || 0), 0);
  const totalExpenseAmount = expenses.reduce((sum, e) => sum + (e.amount || 0), 0);
  const net = totalOrderAmount - totalExpenseAmount;
// Group orders by date
const groupedOrders = {};
const itemCount = {};

orders.forEach(order => {
  const { date, description, amount } = order;

  // Group by date
  if (!groupedOrders[date]) groupedOrders[date] = [];
  groupedOrders[date].push(order);

  // Count individual items (split by comma or "and")
  const items = description
    ?.toLowerCase()
    .split(/,|and|\+/)
    .map(item => item.trim())
    .filter(Boolean);

  items.forEach(item => {
    itemCount[item] = (itemCount[item] || 0) + 1;
  });
});

const totalOrders = orders.length;

const totalExpenses = expenses.reduce((sum, e) => sum + (parseFloat(e.amount) || 0), 0);
const netBalance = totalOrderAmount - totalExpenses;
  orders.forEach(order => {
    const { date, description, amount } = order;

    // Group by date
    if (!groupedOrders[date]) groupedOrders[date] = [];
    groupedOrders[date].push(order);

    // Count individual items (split by comma or "and")
    const items = description
      ?.toLowerCase()
      .split(/,|and|\+/)
      .map(item => item.trim())
      .filter(Boolean);

    items.forEach(item => {
      itemCount[item] = (itemCount[item] || 0) + 1;
    });
  });

 

  const chartOptions = {
    chart: {
      type: 'column'
    },
    title: {
      text: 'Orders vs Expenses'
    },
    xAxis: {
      categories: allDates.map(date => new Date(date).toDateString())
    },
    yAxis: {
      title: {
        text: 'Amount (₹)'
      }
    },
    series: [
      {
        name: 'Orders',
        data: orderChartData,
        color: '#28a745'
      },
      {
        name: 'Expenses',
        data: expenseChartData,
        color: '#dc3545'
      }
    ]
  };

  return (
    <div className="card p-3">
      <h5>Summary</h5>
      
      <HighchartsReact highcharts={Highcharts} options={chartOptions} />

      <div className="mt-4">
        <h6>Totals</h6>
        <table className="table table-bordered">
          <tbody>
            <tr>
              <th>Total Orders</th>
              <td>{`₹${totalOrderAmount.toFixed(2)}`}</td>
            </tr>
            <tr>
              <th>Total Expenses</th>
              <td>{`₹${totalExpenseAmount.toFixed(2)}`}</td>
            </tr>
            <tr>
              <th>Net</th>
              <td style={{ color: net >= 0 ? 'green' : 'red' }}>
                {`₹${net.toFixed(2)}`}
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}
