import React, { useState, useEffect } from 'react';
import { TabView, TabPanel } from 'primereact/tabview';
import 'primereact/resources/themes/lara-light-indigo/theme.css';
import 'primereact/resources/primereact.min.css';
import 'primeicons/primeicons.css';
import 'bootstrap/dist/css/bootstrap.min.css';

import OrderForm from '../src/components/OrderForm';
import OrderList from '../src/components/OrderList';
import ExpenseForm from '../src/components/ExpenseForm';
import ExpenseList from '../src/components/ExpenseList';
import Summary from '../src/components/Summary';

import { getFirestore, collection, addDoc, onSnapshot, query, orderBy } from 'firebase/firestore';
import { app } from '../src/firebase'; // ✅ Make sure this exports your initialized Firebase app

const db = getFirestore(app);

function App() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [orders, setOrders] = useState([]);
  const [expenses, setExpenses] = useState([]);
  const totalOrders = orders.length;
  const totalOrderAmount = orders.reduce((sum, o) => sum + (parseFloat(o.amount) || 0), 0);
  // Calculate days since 25 June 2025
 const firstOrderDate = new Date("2025-06-26");
 const today = new Date();
 const actualDays = Math.floor((today - firstOrderDate) / (1000 * 60 * 60 * 24)) + 1;
 const getDateKey = (d) => {
  if (!d) return 'Invalid';
  try {
    const date = new Date(d);
    if (isNaN(date.getTime())) return 'Invalid';
    // Return date in 'YYYY-MM-DD' format
    return date.toISOString().split('T')[0];
  } catch {
    return 'Invalid';
  }
};

const uniqueDays = new Set(
  orders
    .map(o => getDateKey(o.date))
    .filter(d => d !== 'Invalid')
).size;

const allDateKeys = orders.map(o => getDateKey(o.date)).filter(d => d !== 'Invalid');
console.log("✅ All normalized dates:", allDateKeys.sort());

const uniqueDateKeys = [...new Set(allDateKeys)];
console.log("🗓️ Unique Days:", uniqueDateKeys.length, uniqueDateKeys);
  // const uniqueDays = [...new Set(orders.map(o => new Date(o.date).toISOString().slice(0, 10)))].length;
  const avgOrderAmountPerDay = actualDays ? (totalOrderAmount / actualDays).toFixed(2) : 0;
  const totalExpenses = expenses.reduce((sum, e) => sum + (parseFloat(e.amount) || 0), 0);
  
  const itemCounts = {};
  // Find most frequent tower + flat combo
  const locationCount = {};
  orders.forEach(({ tower, flat }) => {
    if (tower && flat) {
      const key = `${tower.toUpperCase()} - ${flat}`;
      locationCount[key] = (locationCount[key] || 0) + 1;
    }
  });
  const mostCommonLocation = Object.entries(locationCount).sort((a, b) => b[1] - a[1])[0] || ['N/A', 0];
  orders.forEach(order => {
    const desc = order.description?.toLowerCase().trim();
    if (!desc) return;
  
    const parts = desc.split(/,| and | \+ |\/| with /);
  
    parts.forEach(part => {
      const clean = part.trim();
      if (!clean) return;
  
      const match = clean.match(/(?:(\d+)[^\w]*)?(.+)/);
      const qty = match && match[1] ? parseInt(match[1]) : 1;
      let item = match && match[2] ? match[2].trim() : '';
  
      item = item
        .replace(/[^a-z\s]/gi, '')
        .replace(/\b(thali|plate|pcs|piece|pieces|roti|chai|combo|bucket|xtra|extra|order)\b/g, '')
        .replace(/\s+/g, ' ')
        .trim();
  
      if (item.length >= 3) {
        itemCounts[item] = (itemCounts[item] || 0) + qty;
      }
    });
  });
  
  const mostOrderedItemEntry = Object.entries(itemCounts).sort((a, b) => b[1] - a[1])[0] || ['N/A', 0];
  

  
useEffect(() => {
  const itemFrequency = {};

  orders.forEach(order => {
    if (!order.description) return;

    const items = order.description
      .toLowerCase()
      .replace(/ and | \+ |\/|,| with /gi, ',') // normalize separators
      .split(',')
      .map(part => part.trim())
      .filter(Boolean);

    items.forEach(part => {
      const match = part.match(/(?:(\d+)\s*(plate|thali|pcs|piece|pieces)?)?\s*(.+)/i);
      if (match) {
        const quantity = parseInt(match[1]) || 1;
        const itemName = match[3].replace(/[^\w\s]/g, '').trim(); // clean punctuation
        if (itemName.length > 1) {
          itemFrequency[itemName] = (itemFrequency[itemName] || 0) + quantity;
        }
      }
    });
  });

  const sortedItems = Object.entries(itemFrequency)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10);

  console.log("🍽️ Top Ordered Items (with quantity parsing):");
  sortedItems.forEach(([item, count], idx) =>
    console.log(`${idx + 1}. ${item} - ${count} times`)
  );
}, [orders]);
  useEffect(() => {
    const q1 = query(collection(db, 'orders'));
    const unsubOrders = onSnapshot(q1, snapshot => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setOrders(data);
    });

    const q2 = query(collection(db, 'expenses'));
    const unsubExpenses = onSnapshot(q2, snapshot => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setExpenses(data);
    });
    const updateStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', updateStatus);
    window.addEventListener('offline', updateStatus);
    return () => {
      window.removeEventListener('online', updateStatus);
      window.removeEventListener('offline', updateStatus);
    };

    return () => {
      unsubOrders();
      unsubExpenses();
    };

  }, []);

  const addOrder = async (order) => {
    await addDoc(collection(db, 'orders'), order);
  };

  const addExpense = async (expense) => {
    await addDoc(collection(db, 'expenses'), expense);
  };

  return (
    <div className="container mt-4">
      <div className='d-flex justify-content-between align-items-center' >

      <h2 className="text-center mb-4">🧾 Order Manager</h2>
      <div className={`text-${isOnline ? 'success' : 'danger'} text-end mb-2`}>
  {isOnline ? '🟢 Online' : '🔴 Offline - changes will sync later'}
      </div>
</div>
{/* KPIs */}
<div className="row text-center mb-4">
  <div className="col-md-3 col-6 mb-2">
    <div className="p-3 border rounded bg-primary text-white">
      <h6>Total Orders</h6>
      <h4>{totalOrders}</h4>
    </div>
  </div>
  <div className="col-md-3 col-6 mb-2">
    <div className="p-3 border rounded bg-success text-white">
      <h6>Total Sales</h6>
      <h4>₹{totalOrderAmount}</h4>
    </div>
  </div>
  <div className="col-md-3 col-6 mb-2">
    <div className="p-3 border rounded bg-warning text-white">
      <h6>Total Days</h6>
      <h4>{uniqueDays}</h4>
    </div>
  </div>
  <div className="col-md-3 col-6 mb-2">
    <div className="p-3 border rounded bg-info text-white">
      <h6>Avg Sales / Day</h6>
      <h4>₹{avgOrderAmountPerDay}</h4>
    </div>
  </div>


  <div className="col-md-4 col-6 mb-2">
    <div className="p-3 border rounded bg-danger-subtle">
      <h6>Total Expenses</h6>
      <h4>₹{totalExpenses}</h4>
    </div>
  </div>

  <div className="col-md-4 col-6 mb-2">
    <div className="p-3 border rounded bg-warning-subtle">
      <h6>Net Balance</h6>
      <h4>₹{(totalOrderAmount - totalExpenses)}</h4>
    </div>
  </div>
  <div className="col-md-4 col-12 mb-2">
    <div className="p-3 border rounded bg-secondary-subtle">
      <h6 className="text-muted">Most Ordered Item</h6>
      <h5 className="text-dark text-capitalize">{mostOrderedItemEntry?.[0]} - {mostOrderedItemEntry?.[1]} times</h5>
    </div>
  </div>
<div className="col-md-4 col-6 mb-2">
  <div className="p-3 border rounded bg-secondary text-white">
    <h6>Actual Days</h6>
    <h4>{actualDays} days</h4>
  </div>
</div>

<div className="col-md-4 col-6 mb-2">
  <div className="p-3 border rounded bg-primary-subtle">
    <h6 className="text-muted">Most Ordered - Tower/Flat</h6>
    <h5 className="text-dark text-capitalize">{mostCommonLocation[0]} - {mostCommonLocation[1]} orders</h5>
  </div>
</div>
</div>
      <TabView>
        <TabPanel header="Orders">
          <OrderForm add={addOrder} />
          <OrderList />
        </TabPanel>

        <TabPanel header="Expenses">
          <ExpenseForm add={addExpense} />
          <ExpenseList data={expenses} />
        </TabPanel>

        <TabPanel header="Summary">
          <Summary orders={orders} expenses={expenses} />
        </TabPanel>
      </TabView>
    </div>
  );
}

export default App;
